  96  <script>
  97    import { animate } from 'motion';
  98  
  99    const prefersReducedMotion = window.matchMedia('(prefers-reduced-motion: reduce)').matches;
 100  
 101    const animationSequence = [
 102      { selector: '[data-hero-element="badge"]', delay: 0 },
 103      { selector: '[data-hero-element="name"]', delay: 0.08 },
 104      { selector: '[data-hero-element="role"]', delay: 0.16 },
 105      { selector: '[data-hero-element="desc"]', delay: 0.24 },
 106      { selector: '[data-hero-element="cta"]', delay: 0.32 },
 107      { selector: '[data-hero-element="stats"]', delay: 0.45 },
 108    ];
 109  
 110    if (prefersReducedMotion) {
 111      // Skip animation, show all elements immediately
 112      animationSequence.forEach(({ selector }) => {
 113        const el = document.querySelector(selector);
 114        if (el) {
 115          el.style.opacity = '1';
 116          el.style.transform = 'translateY(0)';
 117        }
 118      });
 119    } else {
 120      // Staggered entrance animation
 121      animationSequence.forEach(({ selector, delay }) => {
 122        const el = document.querySelector(selector);
 123        if (el) {
 124          animate(
 125            el,
 126            { opacity: [0, 1], y: [20, 0] },
 127            { duration: 0.6, delay, easing: [0.16, 1, 0.3, 1] }
 128          );
 129        }
 130      });
 131    }
 132  
 133    // --- Cursor Follower ---
 134    const cursor = document.getElementById('cursor-follower');
 135  
 136    if (cursor) {
 137      const onMouseMove = (e: MouseEvent) => {
 138        animate(
 139          cursor,
 140          { x: e.clientX, y: e.clientY },
 141          { duration: 0.08, easing: 'linear' }
 142        );
 143      };
 144  
 145      const onTouchStart = () => {
 146        cursor.style.display = 'none';
 147      };
 148  
 149      const onMouseEnterAfterTouch = () => {
 150        cursor.style.display = '';
 151      };
 152  
 153      document.addEventListener('mousemove', onMouseMove);
 154      document.addEventListener('touchstart', onTouchStart, { once: true });
 155      document.addEventListener('mouseenter', onMouseEnterAfterTouch, { once: true });
 156    }
 157  </script>

