  66  <script>
  67    (() => {
  68      const navbar = document.getElementById('navbar');
  69      const menuToggle = document.getElementById('menu-toggle');
  70      const menuClose = document.getElementById('menu-close');
  71      const mobileMenu = document.getElementById('mobile-menu');
  72      const navLinks = document.querySelectorAll('[data-nav-link]');
  73      const mobileNavLinks = document.querySelectorAll('[data-nav-link-mobile]');
  74      const allLinkSelectors = [...navLinks, ...mobileNavLinks];
  75      const sectionIds = ['work', 'about', 'contact'];
  76  
  77      // --- Glass scroll effect ---
  78      const onScroll = () => {
  79        if (!navbar) return;
  80        if (window.scrollY > 80) {
  81          navbar.classList.add('bg-surface-black/80', 'backdrop-blur-md', 'border-b', 'border-surface-800');
  82        } else {
  83          navbar.classList.remove('bg-surface-black/80', 'backdrop-blur-md', 'border-b', 'border-surface-800');
  84        }
  85      };
  86  
  87      window.addEventListener('scroll', onScroll, { passive: true });
  88      onScroll();
  89  
  90      // --- Active link state via IntersectionObserver ---
  91      const setActiveLink = (activeLink: Element | null) => {
  92        allLinkSelectors.forEach((link) => {
  93          link.classList.remove('bg-surface-800', 'text-surface-200');
  94        });
  95        if (activeLink) {
  96          activeLink.classList.add('bg-surface-800', 'text-surface-200');
  97        }
  98      };
  99  
 100      const observer = new IntersectionObserver(
 101        (entries) => {
 102          for (const entry of entries) {
 103            if (entry.isIntersecting) {
 104              const id = entry.target.id;
 105              const link = document.querySelector(`[data-nav-link][href="#${id}"]`);
 106              if (link) {
 107                setActiveLink(link);
 108              }
 109              const mobileLink = document.querySelector(`[data-nav-link-mobile][href="#${id}"]`);
 110              if (mobileLink) {
 111                setActiveLink(mobileLink);
 112              }
 113            }
 114          }
 115        },
 116        { threshold: 0.6 }
 117      );
 118  
 119      // Set default active state to "Work"
 120      const defaultLink = document.querySelector('[data-nav-link][href="#work"]');
 121      if (defaultLink) {
 122        setActiveLink(defaultLink);
 123      }
 124  
 125      // Observe sections after DOM is ready
 126      const observeSections = () => {
 127        sectionIds.forEach((id) => {
 128          const el = document.getElementById(id);
 129          if (el) observer.observe(el);
 130        });
 131      };
 132  
 133      if (document.readyState === 'loading') {
 134        document.addEventListener('DOMContentLoaded', observeSections);
 135      } else {
 136        observeSections();
 137      }
 138  
 139      // --- Mobile menu ---
 140      if (menuToggle && mobileMenu) {
 141        menuToggle.addEventListener('click', () => {
 142          mobileMenu.classList.remove('hidden');
 143          document.body.style.overflow = 'hidden';
 144        });
 145      }
 146  
 147      const closeMenu = () => {
 148        if (!mobileMenu) return;
 149        mobileMenu.classList.add('hidden');
 150        document.body.style.overflow = '';
 151      };
 152  
 153      if (menuClose) {
 154        menuClose.addEventListener('click', closeMenu);
 155      }
 156  
 157      // Close menu on nav link click
 158      mobileNavLinks.forEach((link) => {
 159        link.addEventListener('click', closeMenu);
 160      });
 161    })();
 162  </script>

