  39      <meta name="twitter:title" content={title} />
  40      <meta name="twitter:description" content={description} />
  41      {ogImage && <meta name="twitter:image" content={ogImage} />}
  42    </head>
  43    <body>
  44      <div id="scroll-bar" role="progressbar" aria-valuenow={0} aria-valuemin={0} aria-valuemax={100}></div>
  45      <Navbar />
  46      <main role="main">
  47        <slot />
  48      </main>
  49  
  50      <script>
  51        (() => {
  52          let ticking = false;
  53  
  54          window.addEventListener('scroll', () => {
  55            if (!ticking) {
  56              requestAnimationFrame(() => {
  57                const scrollTop = window.scrollY;
  58                const docHeight = document.documentElement.scrollHeight;
  59                const winHeight = window.innerHeight;
  60                const scrollable = docHeight - winHeight;
  61                const progress = scrollable > 0 ? (scrollTop / scrollable) * 100 : 0;
  62                document.documentElement.style.setProperty('--scroll-progress', progress + '%');
  63  
  64                const scrollBar = document.getElementById('scroll-bar');
  65                if (scrollBar) {
  66                  scrollBar.setAttribute('aria-valuenow', Math.round(progress).toString());
  67                }
  68  
  69                ticking = false;
  70              });
  71              ticking = true;
  72            }
  73          });
  74        })();
  75      </script>
  76    </body>
  77  </html>

